function sumarDiasIso(fechaIso: string, dias: number) {
  const [anio, mes, dia] = fechaIso.split('-').map(Number);
  const fecha = new Date(anio, mes - 1, dia);
  fecha.setDate(fecha.getDate() + dias);
  const yyyy = fecha.getFullYear();
  const mm = String(fecha.getMonth() + 1).padStart(2, '0');
  const dd = String(fecha.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

function formatearAlumnoListadoOperativo(valor: string | null | undefined) {
  const partes = String(valor || '').split('·').map((parte) => parte.trim()).filter(Boolean).filter((parte) => !/^test nuevo$/i.test(parte));
  if (partes.length === 0) return '-';
  const nombre = partes[0].replace(/^\d+[.)-]?\s*/, '').trim();
  const nivel = partes.find((parte, indice) => indice > 0 && /^(INICIACI[ÓO]N|DEBUT|A\+?|B\+{0,2}|C\+?|D\+?)$/i.test(parte));
  return nivel ? `${nombre} · ${nivel.toUpperCase()}` : nombre;
}

function nombreAlumnoWhatsappPapis(valor: string | null | undefined) {
  const operativo = formatearAlumnoListadoOperativo(valor);
  return operativo
    .replace(
      /\s*·\s*(INICIACI[ÓO]N|DEBUT|A\+?|B\+{0,2}|C\+?|D\+?)\s*$/i,
      ''
    )
    .trim();
}

function nombreEntrenadorWhatsappPapis(valor: string | null | undefined) {
  return String(valor || '')
    .replace(/^\[TEST[^\]]*\]\s*/i, '')
    .replace(/^TEST\s+NUEVO\s*[·:\-]\s*/i, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function entrenadoresWhatsappPapis(valor: string | null | undefined) {
  return String(valor || '')
    .split('+')
    .map((nombre) => nombreEntrenadorWhatsappPapis(nombre))
    .filter(Boolean)
    .join(' + ');
}

function calcularFechasCuatroSesionesIntensivo(
  fechaInicio: string,
  tipo: PlantillaCuatroSesionesIntensivoState['tipo']
) {
  if (!fechaInicio) return [];

  if (tipo === 'cuatro_dias') {
    return [0, 1, 2, 3].map((offset) => sumarDiasIso(fechaInicio, offset));
  }

  if (tipo === 'dos_fines_semana') {
    return [0, 1, 7, 8].map((offset) => sumarDiasIso(fechaInicio, offset));
  }

  return [0, 7, 14, 21].map((offset) => sumarDiasIso(fechaInicio, offset));
}

function nombreTipoCuatroSesionesIntensivo(
  tipo: PlantillaCuatroSesionesIntensivoState['tipo']
) {
  if (tipo === 'cuatro_dias') return '4 días seguidos';
  if (tipo === 'dos_fines_semana') return '2 fines de semana consecutivos';
  if (tipo === 'cuatro_sabados') return '4 sábados';
  return '4 domingos';
}

function grupoEdadIntensivo(fechaNacimiento?: string | null) {
  if (!fechaNacimiento) return 'Sin edad';
  const hoy = new Date();
  const nacimiento = new Date(`${fechaNacimiento}T00:00:00`);
  let edad = hoy.getFullYear() - nacimiento.getFullYear();
  const m = hoy.getMonth() - nacimiento.getMonth();
  if (m < 0 || (m === 0 && hoy.getDate() < nacimiento.getDate())) edad -= 1;
  return edad >= 7 ? 'Mayores' : 'Pequeños';
}

