function PantallaLoginApp({
  onLogin,
  onRecuperarPassword,
}: {
  onLogin: (email: string, password: string) => Promise<void>;
  onRecuperarPassword: (email: string) => Promise<void>;
}) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [cargandoAuth, setCargandoAuth] = useState(false);
  const [recuperandoAuth, setRecuperandoAuth] = useState(false);
  const [errorAuth, setErrorAuth] = useState('');
  const [mensajeAuth, setMensajeAuth] = useState('');

  async function recuperarPassword() {
    setErrorAuth('');
    setMensajeAuth('');

    if (!email.trim()) {
      setErrorAuth('Escribe primero el email de tu cuenta.');
      return;
    }

    try {
      setRecuperandoAuth(true);
      await onRecuperarPassword(email.trim());
      setMensajeAuth(
        'Te hemos enviado un email para crear una contraseña nueva. Revisa también spam o correo no deseado.'
      );
    } catch (error: any) {
      setErrorAuth(
        error?.message ||
          'No se ha podido enviar el email de recuperación.'
      );
    } finally {
      setRecuperandoAuth(false);
    }
  }

  async function enviarLogin(e: React.FormEvent) {
    e.preventDefault();
    setErrorAuth('');
    if (!email.trim() || !password) {
      setErrorAuth('Mete email y contraseña.');
      return;
    }
    try {
      setCargandoAuth(true);
      await onLogin(email.trim(), password);
    } catch (error: any) {
      setErrorAuth(error?.message || 'No se ha podido iniciar sesión.');
    } finally {
      setCargandoAuth(false);
    }
  }

  return (
    <main style={authShellApp}>
      <form onSubmit={enviarLogin} style={authCardApp}>
        <div
          style={{
            display: 'flex',
            gap: 14,
            alignItems: 'center',
            marginBottom: 18,
          }}
        >
          <img
            src="/logo-cabecera-mitico.png"
            alt="Mítico Club"
            style={{
              width: 64,
              height: 64,
              borderRadius: 18,
              objectFit: 'contain',
              background: '#fff',
              border: '1px solid #e5e7eb',
            }}
          />
          <div>
            <p
              style={{
                margin: 0,
                color: '#2563eb',
                fontWeight: 900,
                letterSpacing: 2,
                textTransform: 'uppercase',
                fontSize: 12,
              }}
            >
              Acceso privado
            </p>
            <h1 style={{ margin: '4px 0 0', fontSize: 26 }}>
              Mítico Baby / Ocio
            </h1>
          </div>
        </div>

        <p style={{ marginTop: 0, color: '#475569', lineHeight: 1.45 }}>
          Entra con tu email y contraseña. Si eres entrenador, solo verás tu
          panel de trabajo.
        </p>

        <label
          style={{ display: 'grid', gap: 7, fontWeight: 800, marginBottom: 12 }}
        >
          Email
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={authInputApp}
            placeholder="tu@email.com"
            autoComplete="email"
          />
        </label>

        <label
          style={{ display: 'grid', gap: 7, fontWeight: 800, marginBottom: 16 }}
        >
          Contraseña
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={authInputApp}
            placeholder="Contraseña"
            autoComplete="current-password"
          />
        </label>

        {errorAuth && (
          <div
            style={{
              background: '#fff1f2',
              color: '#be123c',
              border: '1px solid #fecdd3',
              borderRadius: 16,
              padding: 12,
              marginBottom: 12,
              fontWeight: 800,
            }}
          >
            {errorAuth}
          </div>
        )}

        {mensajeAuth && (
          <div
            style={{
              background: '#ecfdf5',
              color: '#047857',
              border: '1px solid #a7f3d0',
              borderRadius: 16,
              padding: 12,
              marginBottom: 12,
              fontWeight: 800,
              lineHeight: 1.4,
            }}
          >
            {mensajeAuth}
          </div>
        )}

        <button
          type="submit"
          disabled={cargandoAuth || recuperandoAuth}
          style={{
            ...authBotonApp,
            opacity: cargandoAuth || recuperandoAuth ? 0.7 : 1,
          }}
        >
          {cargandoAuth ? 'Entrando...' : 'Entrar'}
        </button>

        <button
          type="button"
          disabled={cargandoAuth || recuperandoAuth}
          onClick={recuperarPassword}
          style={{
            width: '100%',
            marginTop: 10,
            border: '1px solid #bfdbfe',
            borderRadius: 16,
            padding: '13px 16px',
            background: '#eff6ff',
            color: '#1d4ed8',
            fontWeight: 900,
            fontSize: 15,
            cursor: 'pointer',
            opacity: cargandoAuth || recuperandoAuth ? 0.7 : 1,
          }}
        >
          {recuperandoAuth
            ? 'Enviando recuperación...'
            : '¿Has olvidado tu contraseña?'}
        </button>
      </form>
    </main>
  );
}

function PantallaCrearPasswordApp({
  sesionInvitacion,
  modo = 'invite',
  onCompletado,
}: {
  sesionInvitacion: SesionAuthApp;
  modo?: 'invite' | 'recovery';
  onCompletado: (sesion: SesionAuthApp) => Promise<void>;
}) {
  const [password, setPassword] = useState('');
  const [password2, setPassword2] = useState('');
  const [cargandoAuth, setCargandoAuth] = useState(false);
  const [errorAuth, setErrorAuth] = useState('');

  async function guardarPassword(e: React.FormEvent) {
    e.preventDefault();
    setErrorAuth('');
    if (password.length < 8) {
      setErrorAuth('La contraseña debe tener mínimo 8 caracteres.');
      return;
    }
    if (password !== password2) {
      setErrorAuth('Las contraseñas no coinciden.');
      return;
    }

    try {
      setCargandoAuth(true);
      await actualizarPasswordInvitacionApp(
        sesionInvitacion.access_token,
        password
      );
      const usuario = await obtenerUsuarioAuthApp(
        sesionInvitacion.access_token
      );
      await onCompletado({ ...sesionInvitacion, user: usuario });
      limpiarUrlAuthApp();
    } catch (error: any) {
      setErrorAuth(error?.message || 'No se ha podido guardar la contraseña.');
    } finally {
      setCargandoAuth(false);
    }
  }

  return (
    <main style={authShellApp}>
      <form onSubmit={guardarPassword} style={authCardApp}>
        <div
          style={{
            display: 'flex',
            gap: 14,
            alignItems: 'center',
            marginBottom: 18,
          }}
        >
          <img
            src="/logo-cabecera-mitico.png"
            alt="Mítico Club"
            style={{
              width: 64,
              height: 64,
              borderRadius: 18,
              objectFit: 'contain',
              background: '#fff',
              border: '1px solid #e5e7eb',
            }}
          />
          <div>
            <p
              style={{
                margin: 0,
                color: '#16a34a',
                fontWeight: 900,
                letterSpacing: 2,
                textTransform: 'uppercase',
                fontSize: 12,
              }}
            >
              {modo === 'recovery'
                ? 'Recuperación de acceso'
                : 'Invitación aceptada'}
            </p>
            <h1 style={{ margin: '4px 0 0', fontSize: 26 }}>
              {modo === 'recovery'
                ? 'Crea una contraseña nueva'
                : 'Crea tu contraseña'}
            </h1>
          </div>
        </div>

        <p style={{ marginTop: 0, color: '#475569', lineHeight: 1.45 }}>
          {modo === 'recovery'
            ? 'Escribe una contraseña nueva. Después entrarás directamente en tu cuenta.'
            : 'Pon tu contraseña para entrar después con email y contraseña desde el móvil.'}
        </p>

        <label
          style={{ display: 'grid', gap: 7, fontWeight: 800, marginBottom: 12 }}
        >
          Nueva contraseña
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={authInputApp}
            placeholder="Mínimo 8 caracteres"
            autoComplete="new-password"
          />
        </label>

        <label
          style={{ display: 'grid', gap: 7, fontWeight: 800, marginBottom: 16 }}
        >
          Repetir contraseña
          <input
            type="password"
            value={password2}
            onChange={(e) => setPassword2(e.target.value)}
            style={authInputApp}
            placeholder="Repite la contraseña"
            autoComplete="new-password"
          />
        </label>

        {errorAuth && (
          <div
            style={{
              background: '#fff1f2',
              color: '#be123c',
              border: '1px solid #fecdd3',
              borderRadius: 16,
              padding: 12,
              marginBottom: 12,
              fontWeight: 800,
            }}
          >
            {errorAuth}
          </div>
        )}

        <button
          type="submit"
          disabled={cargandoAuth}
          style={{ ...authBotonApp, opacity: cargandoAuth ? 0.7 : 1 }}
        >
          {cargandoAuth
            ? 'Guardando...'
            : modo === 'recovery'
            ? 'Guardar contraseña nueva y entrar'
            : 'Guardar contraseña y entrar'}
        </button>
      </form>
    </main>
  );
}

function PantallaAuthErrorApp({
  mensaje,
  onSalir,
}: {
  mensaje: string;
  onSalir: () => void;
}) {
  return (
    <main style={authShellApp}>
      <section style={authCardApp}>
        <h1 style={{ marginTop: 0 }}>Acceso pendiente de configurar</h1>
        <p style={{ color: '#475569', lineHeight: 1.45 }}>{mensaje}</p>
        <button type="button" onClick={onSalir} style={authBotonApp}>
          Volver al login
        </button>
      </section>
    </main>
  );
}

async function ejecutarFuncionPublicaConRespuestaApp<T>(
  nombreFuncion: string,
  body: object
): Promise<T> {
  const respuesta = await fetch(
    `${SUPABASE_URL}/rest/v1/rpc/${encodeURIComponent(nombreFuncion)}`,
    {
      method: 'POST',
      headers: {
        apikey: SUPABASE_ANON_KEY,
        Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    }
  );

  const texto = await respuesta.text();
  let datos: any = null;
  try {
    datos = texto ? JSON.parse(texto) : null;
  } catch {
    datos = texto;
  }

  if (!respuesta.ok) {
    const mensaje =
      typeof datos === 'string'
        ? datos
        : datos?.message || datos?.hint || texto || 'No se pudo completar la operación.';
    throw new Error(mensaje);
  }

  return datos as T;
}

function tokenTestNivelDesdeUrlApp() {
  if (typeof window === 'undefined') return '';
  return new URLSearchParams(window.location.search).get('test_nivel') || '';
}

function PantallaTestNivelPublicoApp({ token }: { token: string }) {
  const [info, setInfo] = useState<TestNivelPublicoInfoApp | null>(null);
  const [respuestas, setRespuestas] =
    useState<TestNivelPublicoRespuestasApp>(testNivelPublicoRespuestasVaciasApp());
  const [cargando, setCargando] = useState(true);
  const [enviando, setEnviando] = useState(false);
  const [enviado, setEnviado] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    let activo = true;
    async function cargar() {
      setCargando(true);
      setError('');
      try {
        const datos = await ejecutarFuncionPublicaConRespuestaApp<TestNivelPublicoInfoApp[]>(
          'obtener_test_nivel_publico_app',
          { p_token: token }
        );
        if (!activo) return;
        const registro = Array.isArray(datos) ? datos[0] : null;
        if (!registro) throw new Error('Este test no está disponible.');
        setInfo(registro);
      } catch (err: any) {
        if (activo) setError(err?.message || 'Este test no está disponible.');
      } finally {
        if (activo) setCargando(false);
      }
    }
    void cargar();
    return () => {
      activo = false;
    };
  }, [token]);

  const preguntas: Array<{
    clave: keyof Omit<TestNivelPublicoRespuestasApp, 'observaciones'>;
    titulo: string;
    ayuda: string;
    opciones: Array<[string, string]>;
  }> = [
    {
      clave: 'experiencia',
      titulo: '1. ¿Cuántos días aproximadamente ha esquiado?',
      ayuda: 'No hace falta recordar el número exacto.',
      opciones: [
        ['A', 'Nunca / será su primer día'],
        ['B', '1–3 días'],
        ['C', '4–10 días'],
        ['D', 'Más de 10 días'],
      ],
    },
    {
      clave: 'desplazamiento',
      titulo: '2. ¿Se desplaza solo con los esquís puestos?',
      ayuda: 'Piensa en terreno sencillo y sin que un adulto lo lleve.',
      opciones: [
        ['A', 'No, necesita ayuda'],
        ['B', 'Algo, pero necesita ayuda con frecuencia'],
        ['C', 'Sí, se desplaza solo'],
      ],
    },
    {
      clave: 'frenado',
      titulo: '3. ¿Puede frenar haciendo cuña?',
      ayuda: 'Nos interesa si puede controlar la velocidad por sí mismo.',
      opciones: [
        ['A', 'No'],
        ['B', 'A veces / necesita indicaciones'],
        ['C', 'Sí, controla la velocidad solo'],
      ],
    },
    {
      clave: 'giros',
      titulo: '4. ¿Hace giros para cambiar de dirección?',
      ayuda: 'Marca lo que haga de forma habitual, no algo que haya hecho una vez.',
      opciones: [
        ['A', 'No'],
        ['B', 'Está empezando a girar'],
        ['C', 'Hace giros en cuña de forma autónoma'],
        ['D', 'Hace algunos giros con los esquís en paralelo'],
      ],
    },
    {
      clave: 'remonte',
      titulo: '5. ¿Qué remonte utiliza sin ayuda?',
      ayuda: 'Marca el remonte más avanzado que utilice con autonomía.',
      opciones: [
        ['A', 'Ninguno'],
        ['B', 'Cinta transportadora'],
        ['C', 'Percha / telesquí'],
        ['D', 'Silla'],
      ],
    },
    {
      clave: 'pista',
      titulo: '6. ¿Por qué terreno baja con seguridad?',
      ayuda: 'Marca dónde puede esquiar sin que un adulto tenga que sujetarlo.',
      opciones: [
        ['A', 'Zona de debutantes'],
        ['B', 'Pista pequeña / sencilla'],
        ['C', 'Pista grande / completa'],
      ],
    },
  ];

  const completo = preguntas.every(({ clave }) => Boolean(respuestas[clave]));

  async function enviarTest() {
    if (!completo || enviando) return;
    setEnviando(true);
    setError('');
    try {
      await ejecutarFuncionPublicaConRespuestaApp<unknown>(
        'responder_test_nivel_publico_app',
        {
          p_token: token,
          p_experiencia: respuestas.experiencia,
          p_desplazamiento: respuestas.desplazamiento,
          p_frenado: respuestas.frenado,
          p_giros: respuestas.giros,
          p_remonte: respuestas.remonte,
          p_pista: respuestas.pista,
          p_observaciones: respuestas.observaciones || null,
        }
      );
      setEnviado(true);
    } catch (err: any) {
      setError(err?.message || 'No se ha podido enviar el test.');
    } finally {
      setEnviando(false);
    }
  }

  if (cargando) {
    return (
      <main style={authShellApp}>
        <section style={authCardApp}>
          <h1 style={{ marginTop: 0 }}>Preparando valoración...</h1>
          <p style={{ color: '#64748b' }}>Un momento, por favor.</p>
        </section>
      </main>
    );
  }

  if (error && !info) {
    return (
      <main style={authShellApp}>
        <section style={authCardApp}>
          <h1 style={{ marginTop: 0 }}>Test no disponible</h1>
          <p style={{ color: '#64748b', lineHeight: 1.5 }}>{error}</p>
        </section>
      </main>
    );
  }

  if (enviado) {
    return (
      <main style={authShellApp}>
        <section
          style={{
            ...authCardApp,
            border: '1px solid #bbf7d0',
            background: 'linear-gradient(135deg, #f0fdf4, #ffffff)',
          }}
        >
          <p style={{ margin: '0 0 5px', color: '#15803d', fontWeight: 900 }}>
            VALORACIÓN ENVIADA
          </p>
          <h1 style={{ margin: 0 }}>¡Gracias!</h1>
          <p style={{ color: '#475569', lineHeight: 1.55 }}>
            Hemos recibido las respuestas de {info?.nombre_completo}. El equipo
            de coordinación las revisará antes de asignar un nivel inicial.
          </p>
          <p style={{ marginBottom: 0, color: '#64748b', fontSize: 13 }}>
            Ya puedes cerrar esta página.
          </p>
        </section>
      </main>
    );
  }

  return (
    <main
      style={{
        ...authShellApp,
        alignItems: 'flex-start',
        padding: 'max(18px, env(safe-area-inset-top)) 14px max(28px, env(safe-area-inset-bottom))',
      }}
    >
      <section
        style={{
          width: 'min(720px, 100%)',
          margin: '0 auto',
          display: 'grid',
          gap: 14,
        }}
      >
        <article
          style={{
            ...authCardApp,
            width: '100%',
            maxWidth: 'none',
            background: 'linear-gradient(135deg, #eff6ff, #ffffff 52%, #f0fdf4)',
          }}
        >
          <p
            style={{
              margin: '0 0 5px',
              color: '#2563eb',
              fontSize: 11,
              fontWeight: 950,
              letterSpacing: '0.08em',
            }}
          >
            MÍTICO BABY · NIVEL INICIAL
          </p>
          <h1 style={{ margin: 0, fontSize: 25 }}>{info?.nombre_completo}</h1>
          <p style={{ margin: '7px 0 0', color: '#475569' }}>
            Modalidad: <strong>{info?.modalidad}</strong>
          </p>
          <div
            style={{
              marginTop: 12,
              padding: 12,
              borderRadius: 14,
              background: '#fff',
              border: '1px solid #dbeafe',
              color: '#475569',
              lineHeight: 1.45,
            }}
          >
            No necesitamos que conozcas su “nivel”. Marca únicamente lo que has
            visto hacer al niño/a. Son 6 preguntas y se tarda aproximadamente un minuto.
          </div>
        </article>

        {preguntas.map((pregunta) => (
          <article
            key={pregunta.clave}
            style={{
              ...authCardApp,
              width: '100%',
              maxWidth: 'none',
              padding: 16,
            }}
          >
            <h2 style={{ margin: 0, fontSize: 18, lineHeight: 1.3 }}>
              {pregunta.titulo}
            </h2>
            <p style={{ margin: '5px 0 12px', color: '#64748b', fontSize: 13 }}>
              {pregunta.ayuda}
            </p>
            <div style={{ display: 'grid', gap: 8 }}>
              {pregunta.opciones.map(([codigo, texto]) => {
                const activo = respuestas[pregunta.clave] === codigo;
                return (
                  <button
                    key={codigo}
                    type="button"
                    onClick={() =>
                      setRespuestas({
                        ...respuestas,
                        [pregunta.clave]: codigo,
                      })
                    }
                    style={{
                      minHeight: 48,
                      padding: '10px 12px',
                      borderRadius: 14,
                      border: activo
                        ? '2px solid #2563eb'
                        : '1px solid #cbd5e1',
                      background: activo ? '#2563eb' : '#ffffff',
                      color: activo ? '#ffffff' : '#334155',
                      textAlign: 'left',
                      fontWeight: 850,
                      boxShadow: activo
                        ? '0 8px 18px rgba(37,99,235,.18)'
                        : 'none',
                    }}
                  >
                    <strong style={{ marginRight: 8 }}>{codigo}.</strong>
                    {texto}
                  </button>
                );
              })}
            </div>
          </article>
        ))}

        <article
          style={{
            ...authCardApp,
            width: '100%',
            maxWidth: 'none',
            padding: 16,
          }}
        >
          <label style={{ display: 'grid', gap: 7, fontWeight: 900 }}>
            Observaciones importantes (opcional)
            <textarea
              value={respuestas.observaciones}
              maxLength={500}
              onChange={(e) =>
                setRespuestas({
                  ...respuestas,
                  observaciones: e.target.value,
                })
              }
              rows={4}
              placeholder="Miedo, ayuda en remontes, lesión, algo que debamos saber..."
              style={{
                width: '100%',
                border: '1px solid #cbd5e1',
                borderRadius: 14,
                padding: 12,
                resize: 'vertical',
                fontSize: 16,
              }}
            />
          </label>
        </article>

        {error && (
          <div
            style={{
              padding: 12,
              borderRadius: 14,
              background: '#fef2f2',
              border: '1px solid #fecaca',
              color: '#b91c1c',
              fontWeight: 800,
            }}
          >
            {error}
          </div>
        )}

        <button
          type="button"
          disabled={!completo || enviando || !info?.puede_responder}
          onClick={enviarTest}
          style={{
            minHeight: 54,
            border: 0,
            borderRadius: 16,
            padding: '12px 16px',
            background:
              completo && !enviando && info?.puede_responder
                ? '#16a34a'
                : '#cbd5e1',
            color: '#ffffff',
            fontSize: 16,
            fontWeight: 950,
            cursor:
              completo && !enviando && info?.puede_responder
                ? 'pointer'
                : 'not-allowed',
          }}
        >
          {enviando ? 'Enviando...' : 'Enviar valoración'}
        </button>
      </section>
    </main>
  );
}

