  const gestionarDiaDisponibilidad = (
    claveDia: string,
    event: React.SyntheticEvent<HTMLDetailsElement>
  ) => {
    if (event.target !== event.currentTarget) return;

    if (event.currentTarget.open) {
      setDiaDisponibilidadAbierto(claveDia);
      return;
    }

    // El día seleccionado permanece abierto. Solo se cierra al abrir otro día.
    setDiaDisponibilidadAbierto((actual) =>
      actual === claveDia ? claveDia : actual
    );
  };

  const cerrarAcordeonesHermanos = (
    event: React.SyntheticEvent<HTMLDetailsElement>
  ) => {
    if (event.target !== event.currentTarget) return;

    const actual = event.currentTarget;
    if (!actual.open) return;

    const contenedor = actual.parentElement;
    if (!contenedor) return;

    Array.from(contenedor.children).forEach((elemento) => {
      if (
        elemento instanceof HTMLDetailsElement &&
        elemento !== actual &&
        elemento.open
      ) {
        elemento.open = false;
      }
    });
  };

  const enfocarAcordeonEntrenadorAlAbrir = (
    event: React.MouseEvent<HTMLElement>
  ) => {
    const detalle = event.currentTarget.closest('details');
    if (!(detalle instanceof HTMLDetailsElement) || detalle.open) return;

    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        detalle.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        });
      });
    });
  };

  const irASeccionGrupoEntrenador = (
    seccion: 'asistencia' | 'trabajo' | 'observaciones',
    grupoDomId: string
  ) => {
    setSeccionGrupoEntrenador(seccion);

    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        const objetivo = document.getElementById(
          `${grupoDomId}-${seccion}`
        );
        if (!objetivo) return;

        const ficha = objetivo.closest(
          '.trainer-group-card.is-sheet-open'
        ) as HTMLElement | null;

        if (
          ficha &&
          window.matchMedia('(max-width: 719px)').matches
        ) {
          ficha.scrollTo({
            top: Math.max(0, objetivo.offsetTop - 150),
            behavior: 'smooth',
          });
          return;
        }

        objetivo.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        });
      });
    });
  };

